from pathlib import Path
import shutil, datetime, re, sys, subprocess
root=Path.cwd(); app=root/'app.py'; td=root/'templates'
if not app.exists() or not td.exists(): sys.exit('Run from PIMCO_AI project root.')
stamp=datetime.datetime.now().strftime('%Y%m%d-%H%M%S'); backup=root/'PIMCO_WALLET_BACKUP'/stamp; backup.mkdir(parents=True,exist_ok=True)
shutil.copy2(app,backup/'app.py')
for n in ('deposit.html','withdraw.html'):
 f=td/n
 if f.exists(): shutil.copy2(f,backup/n)
src=app.read_text(); m=re.search(r"@app\.route\(['\"]/?withdraw['\"].*?\ndef withdraw\(\):",src,re.S)
if not m: sys.exit('Could not locate /withdraw handler; app.py unchanged.')
nxt=re.search(r'\n@app\.route',src[m.end():]); end=m.end()+nxt.start() if nxt else len(src); block=src[m.start():end]
block=re.sub(r'if amount\s*<=?\s*0\s*or','if amount < 3000 or',block,count=1)
if 'if amount < 3000' not in block:
 pos=re.search(r'\n\s*(?:fee\s*=|with db\(\))',block)
 if pos: block=block[:pos.start()]+'\n        if amount < 3000:\n            flash(\'Minimum withdrawal is UGX 3,000.\', \'error\')\n            return redirect(url_for(\'withdraw\'))\n'+block[pos.start():]
app.write_text(src[:m.start()]+block+src[end:])
